-- State transitions declared for FileShare: an undeclared move is refused.
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION bucket.file_shares_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('active', 'exhausted'), ('active', 'expired'), ('active', 'revoked'))
       ) THEN
        RAISE EXCEPTION 'state_transition_not_declared: file_shares.status % -> %', OLD."status", NEW."status"
            USING ERRCODE = 'check_violation', COLUMN = 'status', CONSTRAINT = 'tg_file_shares__state_transition_not_declared';
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS file_shares_status_transition_check ON bucket.file_shares;
CREATE TRIGGER file_shares_status_transition_check
    BEFORE UPDATE OF "status" ON bucket.file_shares
    FOR EACH ROW EXECUTE FUNCTION bucket.file_shares_status_transition_check();
